#!/usr/bin/env node
// Runs the upstream eval (eval/evaluate.ts) on a vault generated by obsidian-test-fixture's `vi-search` preset
// or on the smoke vault. The vault is always a throw-away copy: upstream eval writes its database into the vault
// directory and rebuilds it. See README.md in this folder.
//
// node vantt/eval/vi/run-eval.mjs [--smoke] [--otf <path to otf.mjs>] [--out <result.json>] [--k 10] [--rerank] [--baseline] [--update-golden]
//                                 [--ohs <OHS tree>] [--lang-pack <module or path>] [--lang-options <json>] [--accented-sanity]
// node vantt/eval/vi/run-eval.mjs --compare <a.json> <b.json> [--out <diff.json>]
//
// Upstream stores note paths in NFD (src/content/text-normalization.ts) and the eval compares paths as strings, so the
// committed golden sets carry NFD paths. The fixture writes NFC file names; `toNfdPaths` converts its golden set.
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { npmCommand } from '../../scripts/lib/proc.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const FIXTURE_TAG = 'v0.12.0';
const GOLDEN = path.join(here, 'golden-set.json');
const SMOKE_GOLDEN = path.join(here, 'smoke-golden-set.json');
const SMOKE_VAULT = path.join(here, 'smoke-vault');

const args = process.argv.slice(2);
const flag = (n) => args.includes(n);
const value = (n) => (args.includes(n) ? args[args.indexOf(n) + 1] : undefined);
const k = value('--k') ?? '10';
const smoke = flag('--smoke');
// The OHS tree to evaluate: this repository, or another checkout/worktree that has eval/evaluate.ts and node_modules.
const repoRoot = path.resolve(value('--ohs') ?? path.resolve(here, '../../..'));
const langPack = value('--lang-pack');
const langOptions = value('--lang-options');
const FOLD_CATEGORIES = ['vi-unaccented', 'vi-dd'];

// --compare a.json b.json: per-category deltas of two result files (b minus a), printed and optionally written.
if (flag('--compare')) {
  const [fa, fb] = args
    .slice(args.indexOf('--compare') + 1, args.indexOf('--compare') + 3)
    .map((f) => path.resolve(f));
  const [a, b] = [fa, fb].map((f) => JSON.parse(fs.readFileSync(f, 'utf8')));
  const METRICS = ['ndcg_5', 'mrr', 'hit_1', 'hit_3', 'hit_5', 'recall_k'];
  const round = (x) => Math.round(x * 1000) / 1000;
  const diff = (x, y) =>
    Object.fromEntries(METRICS.map((m) => [m, { a: x[m], b: y[m], delta: round(y[m] - x[m]) }]));
  const out = {
    a: { file: fa, meta: a.meta },
    b: { file: fb, meta: b.meta },
    summary: diff(a.summary, b.summary),
    by_category: Object.fromEntries(
      Object.keys(a.by_category).map((c) => [c, diff(a.by_category[c], b.by_category[c])]),
    ),
    // queries whose Hit@5 changed
    changed_queries: a.per_query.flatMap((q, i) => {
      const r = b.per_query[i];
